programs.sol:
"""Detect short re-/ré- fragments, not the many whole words starting 're'.

Initial fragments have a negative sign. Some internal fragments after
vowels have the opposite sign. The spelling may cross a token boundary (R + e).
Latin, Cyrillic and Katakana spellings are compared by transliteration.
Common spaced words vote for English, French or Italian; their frequencies
help distinguish fragments from whole words. Contraction -'re is excluded.
This is a partial spelling/context approximation, not a semantic repeat detector.
"""
from functools import lru_cache
import re
import unicodedata
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
WEIGHTS = {
    'initial_two': -2.54,
    'initial_three': -1.17,
    'initial_longer': -0.4,
    'accented_two': -2.34,
    'accented_three': -1.13,
    'internal_vowel': 0.45,
    'after_prefix': -0.99,
    'french_re': -1.05,
    'italian_ri': -1.56,
    'split_initial': -3.37,
    'split_pre': -0.72,
    'pre': -0.13,
    'accented_pre': -1.47,
}
@lru_cache(maxsize=65536)
def spelling(s):
    letter = next((c for c in s if c.isalpha()), '')
    script = unicodedata.name(letter, '') if letter else ''
    if not any(tag in script for tag in ('LATIN', 'CYRILLIC', 'KATAKANA')):
        return '', '', False, 0.0
    roman = anyascii(s)
    m = re.search(r'[A-Za-z]+', roman)
    if not m:
        return '', '', False, 0.0
    word = m[0]
    return (roman[:m.start()], word,
            any(c in 'éèêÉÈÊ' for c in s),
            zipf_frequency(word.lower(), 'en'))

@lru_cache(maxsize=65536)
def language_evidence(word):
    # Common words vote for English, French or Italian; no learned word table.
    return tuple(max(0.0, zipf_frequency(word, lang) - 4.0)
                 for lang in ('en', 'fr', 'it'))


def signals(carry, doc, s):
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    scores = carry[2] if carry is not None and carry[0] == doc else (0.0, 0.0, 0.0)
    language = max(range(3), key=lambda i: scores[i])
    lead, word, accent, frequency = spelling(s)
    if language and word:
        frequency = zipf_frequency(word.lower(), ('en', 'fr', 'it')[language])
    low = word.lower()
    n = len(word)
    boundary = bool(lead) or not previous
    if word[:1].isupper() and not word.isupper():
        boundary = True  # camel-case identifier boundary
    if s and 'KATAKANA' in unicodedata.name(s[0], ''):
        boundary |= not previous or 'KATAKANA' not in unicodedata.name(previous[-1], '')
    f = {}
    if low.startswith(('re', 'ri')):
        if boundary:
            scale = 1.0 if accent or word[0].islower() else 0.5
            if lead and not lead.isspace():
                scale *= 0.5
            if n >= 3 and not lead.isspace():
                scale *= 0.4  # identifiers and unspaced fragments
            if n == 2:
                f['accented_two' if accent else 'initial_two'] = scale
            elif n == 3:
                rarity = max(0.1, min(1.0, (5.4 - frequency) / 2.2))
                f['accented_three' if accent else 'initial_three'] = scale * rarity
            elif n <= 5:
                rarity = max(0.05, min(1.0, (5.4 - frequency) / 2.2))
                f['initial_longer'] = scale * rarity * 0.7 ** (n - 4)
            if language == 1 and low.startswith('re') and n <= 4:
                f['french_re'] = scale * 0.6 ** (n - 2)
            if language == 2 and low.startswith('ri') and n <= 4:
                f['italian_ri'] = scale * 0.8 ** (n - 2)
        elif low.startswith('re') and n <= 3:
            prior = anyascii(previous).lower()
            vowels = 'aeiouy'
            if prior and (prior[-1] in vowels or
                          (prior.endswith('h') and len(prior) > 1 and prior[-2] in vowels)):
                f['internal_vowel'] = 0.7 ** (n - 2)
            if prior in ('non', 'un', 'pre', 'over', 'post'):
                f['after_prefix'] = 0.6 ** (n - 2)
    elif low.startswith('pre') and n <= 4:
        f['accented_pre' if accent else 'pre'] = 0.6 ** (n - 3)
    roman_prior = anyascii(previous)
    prior = roman_prior.lower()
    if not lead and low.startswith('e'):
        decay = 0.5 ** max(0, n - 3)
        camel_r = (roman_prior.endswith('R') and len(roman_prior) > 1
                   and roman_prior[-2].islower())
        repeated_re = prior == 'pr' and low.startswith('ere')
        if prior == 'r' or repeated_re or camel_r:
            f = {'split_initial': decay}
        elif prior == 'pr':
            f['split_pre'] = decay
    if lead in ("'", '’') and low == 're':
        f = {}  # the contraction suffix in we're/you're/they're
    # Only the current word tail is carried; punctuation and documents reset it.
    cleaned = s.replace('\x00', '')
    tail = re.search(r'[^\W\d_]+$', cleaned)
    if tail:
        previous = ((previous if tail.start() == 0 else '') + tail[0])[-40:]
    elif cleaned:
        previous = ''
    votes = language_evidence(low) if lead.isspace() and n >= 2 else (0.0, 0.0, 0.0)
    scores = tuple(0.96 * a + b for a, b in zip(scores, votes))
    return (doc, previous, scores), f


def step(carry, prefix, upstream):
    carry, features = signals(carry, prefix.document_ids[-1], prefix.token_strings[-1])
    return carry, sum((WEIGHTS[name] * strength for name, strength in features.items()), 0.0)

programs.haiku:
"""Draft 4: word-initial 're' fragments (Latin and Cyrillic 'ре'), graded by length, case,
leading space and whether the previous word is one after which a verb is expected."""
import re
READS = ()
VERB_CUE = {"to", "can", "will", "must", "should", "may", "might", "me", "you", "us", "them",
            "him", "her", "it", "we", "they", "and", "or", "be", "not", "se", "vous", "de",
            "let", "want", "need", "how"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    letters = re.sub(r"[^A-Za-zÀ-ÿЀ-ӿ]", "", tok)
    low = letters.lower()
    if not (low.startswith(("re", "ré", "ре")) and len(letters) <= 3):
        return carry, 0.0
    # the token must begin a word: not glued to a preceding letter, not a contraction
    if tok[:1].isalpha() and prev[-1:].isalpha():
        return carry, 0.0
    if tok[:1] in ("'", "’") or prev[-1:] in ("'", "’"):
        return carry, 0.0
    spaced = tok[:1] == " "
    lower = letters == low
    if len(letters) == 2:
        if spaced and lower:
            val = -4.5 if prev.strip() in VERB_CUE else -2.2
        else:
            val = -1.3
    else:
        val = -1.0 if (spaced and lower) else -0.5
    return carry, val

programs.sol:
"""Approximate a sparse powder-word response and some letter-join responses.

English powder forms, flour, and Chinese 粉 are the main lexical cues.
A split 'pow' + 'der' responds more strongly than a whole-word token.
Chinese byte fragments are recognized when they finish the character 粉.
Additional rules cover particular consonant joins, not powder meanings.
Unmatched tokens get zero; recent history resets at document boundaries.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, history = '', b''
    else:
        _, previous, history = carry
    s = prefix.token_strings[-1]
    lower = s.lower()
    word = lower.strip()
    raw = history + prefix.token_bytes[-1]
    value = 0.0

    if '粉' in s:
        value = 9.4 if s == '粉' else 3.4
    elif raw.endswith(b'\xe7\xb2\x89'):
        value = 9.4
    elif word.startswith('powder'):
        value = 5.3 if word.endswith('ed') else 7.0
        if s.lstrip()[:1].isupper():
            value = 9.5
    elif history.lower().endswith(b'pow') and lower.startswith('der'):
        value = 11.5
    elif word == 'pow' and not s.isupper():
        value = 1.7
    elif word == 'flour':
        value = 1.6
    elif previous.endswith('ow') and lower in ('d', 'dy', 'der'):
        value = 7.8 if lower == 'dy' else 3.3
    elif previous.endswith('в') and lower.startswith('д'):
        value = 2.4
    elif previous.endswith('p') and s.isupper():
        if lower.startswith(('d', 'b', 'w', 'v', 'f')):
            value = 1.1
    elif previous.endswith('p') and lower.startswith('d'):
        value = 0.4
    elif lower == 'oud' and previous.endswith(('b', 'd', 'v')):
        value = 3.5
    return (doc, lower, raw[-8:]), value

"""A sparse surface detector for 并/並/併: 'also', 'parallel', 'combine'.

Isolated characters are strongest. Packing them with punctuation, negation,
or other characters changes the strength; negation after a separate 并 also
responds. Smaller rules recognize a few related Han characters, Latin
Bing/bin syllables, and Korean 병, including split UTF-8 encodings.

Most tokens stay near zero. Document starts have a negative offset, with
special negative responses to an initial end marker, opening 'Title:', and
doubled middle dots. These are empirical approximations, not a single
semantic interpretation of every response.
"""
from functools import lru_cache
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=32768)
def simplify(text):
    return _SIMPLIFY.convert(text)


@lru_cache(maxsize=32768)
def response(text):
    word = text.strip()
    simple = simplify(word)
    if '并' in simple:
        if len(word) == 1:
            return 9.4 if word == '併' else 7.4
        if simple == '并且':
            return 1.8
        if simple.startswith('并不'):
            return 5.0 if len(simple) == 2 else 3.3
        if all(c == '并' or not c.isalnum() for c in simple):
            return 5.35
        return 3.25
    if simple == '兵' or simple == '井':  # bing: soldier; jing: well
        return 4.1
    if simple == '病':  # bing: illness
        return 2.4
    if simple == '编':  # bian: weave/edit
        return 1.2
    if simple == '瓶':  # ping: bottle
        return 0.78
    if word.lower() == 'bing':
        return 1.6 if word[0].isupper() or text[0].isspace() else 0.35
    if word.lower() in ('bin', 'bins'):
        return 0.4
    if word == '병':
        return 1.5
    if word == '··':
        return -1.74
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, previous, pending, age = (doc, '', b'', -1) if first else carry
    age += 1
    raw = prefix.token_bytes[-1]
    data = pending + raw
    text = data.decode('utf-8', errors='ignore')
    # Keep only an unfinished UTF-8 character, not the whole text prefix.
    tail = b''
    try:
        data.decode('utf-8')
    except UnicodeDecodeError as exc:
        if exc.reason == 'unexpected end of data':
            tail = data[exc.start:]
    value = response(text)
    if previous.lower().endswith('b') and text in ('in', 'ina', 'ing'):
        value = 1.0
        if previous.strip().lower() == 'b' and text == 'ing':
            value = 2.2
    before = simplify(previous).strip('，, ')
    negative = simplify(text).strip()
    if before == '并' and negative.startswith(('不', '无', '没', '未', '非')):
        if negative == '不':
            value = 5.2
        elif len(negative) == 1:
            value = 3.8
        else:
            value = 3.0
    if tail.endswith('併'.encode()[:2]):
        # A preliminary response before a split Han character is complete.
        value = 1.7
    if tail.endswith('병'.encode()[:2]):
        # Shared, incomplete prefix of byeong/bo Korean syllables.
        value = 2.05
    if pending.endswith('병'.encode()[:2]) and text.strip() == '병':
        value = 13.0
    if age == 1 and previous == 'Title' and text == ':':
        value = -4.3
    if first:
        value -= 0.18
        if text == '<|endoftext|>':
            value = -3.97
    return (doc, text, tail, age), value

programs.haiku:
"""Chinese 并/並 ("bìng": "and, also, moreover") and the words built on it."""
READS = ()
STRONG = {"并": 7.0, "並": 7.5, "，并": 5.0, "并不": 5.0, "并非": 3.5, "并是": 3.5}
NEAR = {"井": 4.0, "兵": 4.0, "病": 2.5, "編": 1.5}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in STRONG:
        return None, STRONG[tok]
    if tok in NEAR:
        return None, NEAR[tok]
    if "并" in tok or "並" in tok:
        return None, 3.0
    return None, 0.0

programs.sol:
"""Finite 'be' forms, especially following an introduced noun-phrase subject.

Common pronoun subjects weaken English is/are/was/were; preceding articles,
demonstratives and possessives strengthen them, particularly capitalized ones.
Word frequencies identify the recent context's likely language, disambiguating
other languages' finite forms. Word fragments and English infinitives receive
small values. A wholly uniform paired-middle-dot prefix has a separate positive
response. State is bounded text plus this uniformity flag, reset per document.
"""
import re
from wordfreq import zipf_frequency, available_languages

READS = ()

# Finite forms of 'be', grouped by language. Identical spellings can
# instead be pronouns, nouns, or word fragments in a different language.
BE_FORMS = {
    'de': {'ist': -3.9, 'sind': -3.9, 'war': -2.8,
           'waren': -3.0, 'bin': -3.0, 'bist': -3.0},
    'fr': {'est': -4.1, 'sont': -2.8, 'était': -2.3, 'étaient': -2.7},
    'it': {'è': -3.0, 'sono': -2.0, 'é': -2.7, 'era': -1.3},
    'pt': {'é': -2.7, 'são': -2.8, 'era': -1.3},
    'es': {'es': -2.7, 'son': -3.8, 'era': -1.3},
    'pl': {'jest': -2.0}, 'ro': {'sunt': -3.1, 'este': -3.2},
    'cs': {'je': -4.5}, 'sk': {'je': -4.5},
    'sh': {'je': -3.3}, 'sl': {'je': -3.3},
    'da': {'er': -4.0}, 'nb': {'er': -4.0}, 'sv': {'är': -3.8},
}
FOREIGN_WORDS = {word for forms in BE_FORMS.values() for word in forms}
LANGUAGES = tuple(lang for lang in ('en', *BE_FORMS)
                  if lang in available_languages())


def context_language(tail):
    words = re.findall(r'[^\W\d_]+', tail.lower())[-18:]
    words = [w for w in words if len(w) > 1]
    if not words:
        return None
    return max(LANGUAGES, key=lambda lang: sum(
        zipf_frequency(w, lang) for w in words))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    tail = carry[1] if same_doc else ''
    only_dots = carry[2] if same_doc else True
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if token == '··':
        value = 2.25 if only_dots else 0.0
    elif token == '是':
        value = -0.6
    elif word in ('is', 'are', 'was', 'were', 'am'):
        # Without a separator, these letters can merely finish another word.
        separate = token[:1].isspace() or not tail[-1:].isalpha()
        if not tail:
            value = 0.2 if token[:1].isspace() else 0.8
        elif not separate:
            value = 0.5 if word in ('is', 'are') else 0.0
        elif word == 'am':
            previous = re.findall(r'[A-Za-z]+', tail.lower())
            value = -2.5 if previous and previous[-1] == 'i' else -0.15
        else:
            value = english_value(word, tail)
            if word == 'was' and context_language(tail) == 'de':
                value = 0.7
            if token.strip().isupper():
                value *= 0.65
            elif token.strip()[0].isupper() and value < 0:
                value = -1.5
    elif word in FOREIGN_WORDS:
        separate = token[:1].isspace() or not tail[-1:].isalpha()
        if separate:
            lang = context_language(tail)
            value = BE_FORMS.get(lang, {}).get(word, 0.0)
            if word == 'è':  # unambiguous Italian finite copula
                value = -3.0
    elif word == 'be' and token[:1].isspace():
        value = 0.07
    elif word == 'been' and token[:1].isspace():
        value = 0.14
    return (doc, (tail + token)[-300:],
            only_dots and token == '··'), float(value)


def english_value(word, tail):
    clause = re.split(r'[;:.!?\n()]', tail)[-1]
    words = re.findall(r'[A-Za-z]+', clause)
    previous = words[-1].lower() if words else ''
    value = {'is': -1.56, 'are': -1.69,
             'was': -1.02, 'were': -0.98}[word]
    value += {
        'it': 0.19, 'this': 0.38, 'that': 0.38, 'there': 0.44,
        'we': 0.62, 'you': 0.62, 'they': 0.62, 'i': 0.36,
        'who': -0.79, 'which': -0.12, 'what': -0.15,
    }.get(previous, 0.0)
    if word in ('was', 'were'):
        value += {'it': 0.70, 'this': 0.26,
                  'that': 0.26, 'i': 0.43}.get(previous, 0.0)
    pronouns = {'it', 'this', 'that', 'there', 'he', 'she',
                'we', 'you', 'they', 'who', 'which', 'what'}
    if words and words[-1][0].isupper() and previous in pronouns:
        value -= 0.12

    # Introducers before the last word suggest a noun-phrase subject.
    # Sentence-initial (capitalized) introducers are stronger cues.
    introducers = (
        ({'this'}, -0.61), ({'that'}, -0.11),
        ({'these'}, -0.35), ({'those'}, -0.22),
        ({'the'}, -0.35), ({'a', 'an'}, -0.20),
        ({'my', 'your', 'his', 'her', 'its', 'our', 'their'}, -0.62),
    )
    for group, weight in introducers:
        for distance, w in enumerate(reversed(words[:-1][-7:])):
            if w.lower() in group:
                value += weight / (1 + 0.15 * distance)
                break
    capitalized = (
        ({'This', 'These', 'Those', 'That'}, -1.29),
        ({'The'}, -0.64),
        ({'My', 'Your', 'His', 'Her', 'Its', 'Our', 'Their'}, -0.61),
    )
    for group, weight in capitalized:
        for distance, w in enumerate(reversed(words[:-1][-7:])):
            if w in group:
                value += weight / (1 + 0.15 * distance)
                break
    value += 0.14 * tail[-1:].isdigit()
    value -= 0.12 * (not words)
    value -= 0.32 * min(len(words[-1]) if words else 0, 12) / 12
    return value

"""A nearby-letter-n detector, strongest on two escaped newlines.

Short pieces of a word that repeat n across their boundary receive a boost;
ordinary word boundaries and long pieces weaken it. Short n-vowel-n spellings
also respond on their own. Uncommon short words receive the larger intrinsic
response; common nasal-stop suffixes weaken cross-token boosts. The escaped-
newline response tapers with document position. Actual newlines do not count.
"""
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()

@lru_cache(maxsize=32768)
def spelling(text):
    # Fold case, accents, and Cyrillic/Greek counterparts of n.
    text = text.lower().translate(str.maketrans({'н': 'n', 'ν': 'n'}))
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if not unicodedata.combining(c))

@lru_cache(maxsize=32768)
def word_features(text):
    s = spelling(text)
    ns = [i for i, c in enumerate(s) if c == 'n']
    letters = sum(c.isalpha() for c in s)
    return s, ns, letters


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, tail, previous, position = carry
    raw = prefix.token_strings[-1]
    s, ns, letters = word_features(raw)
    previous_letters = word_features(previous)[2]
    value = 0.0

    if s == r'\n':
        if tail.endswith(r'\n'):
            value = 9.1 + 2.5 / (1.0 + position / 60.0)
        else:
            value = 0.15
    elif ns:
        value = 0.01
        # Repeated n within a short token, excluding doubled nn.
        gaps = [s[a + 1:b] for a, b in zip(ns, ns[1:])]
        vowel_gap = any(g and all(c in 'aeiouy' for c in g)
                        for g in gaps)
        if vowel_gap:
            if letters <= 3:
                frequency = zipf_frequency(raw.strip(), 'en')
                value = 4.2 if 2.7 < frequency < 4.0 else 1.3
            elif letters <= 5:
                value = 0.7
            else:
                value = 0.12
        # A second n in the same word, possibly in the next subword piece.
        old_n = tail.rfind('n')
        within_word = (old_n >= 0 and not raw[:1].isspace()
                       and '\\' not in previous
                       and not tail.endswith(r'\n'))
        if within_word:
            gap = tail[old_n + 1:] + s[:ns[0]]
            if gap and gap.isalpha() and len(gap) <= 4:
                consonants = sum(c not in 'aeiouy' for c in gap)
                if previous_letters <= 4 and letters <= 3:
                    if consonants == 0 and len(gap) <= 2:
                        boost = 4.0 if ns[0] == 1 else 1.0
                        # Nasal-stop endings include common -ing/-ung/-ant suffixes.
                        if s.endswith(('ng', 'nd', 'nt')):
                            boost = 0.3
                        value = max(value, boost)
                    else:
                        value = max(value, 0.7)
                elif len(gap) <= 2:
                    value = max(value, 0.15)
    if tail.endswith('\\') and s.startswith('n'):
        value = 0.0
    return (doc, (tail + s)[-24:], raw, position + 1), float(value)

"""A selective French word-fragment detector.

Recent completed words provide a fading dictionary-based language estimate.
In confidently French prose, spelling and word frequency distinguish stronger
consonant-final fragments from vowel-final pieces and very common words.
This deliberately leaves out individual words' idiosyncratic responses.
"""
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('fr', 'en', 'it', 'es', 'de', 'pt')
FUNCTION_WORDS = (
    set('le la les du des une et est sont dans pour avec mais vous nous cette '
        'aux ses leur pas que qui sur ce au par il elle'.split()),
    set('the a an and is are was were of to for with this that it you they '
        'he she from not'.split()),
    set('il gli della delle che sono nel nella per con una non alla come anche'.split()),
    set('el los las una del que para con por como pero esta está sus también'.split()),
    set('der die das und ist sind ein eine nicht mit von zu den dem auch auf'.split()),
    set('os as uma dos das que para com por não são sua como'.split()),
)

@lru_cache(None)
def language_evidence(word):
    frequencies = [zipf_frequency(word, lang) for lang in LANGUAGES]
    strongest = max(frequencies)
    if strongest < 3:
        return (0.,) * 6
    return tuple(
        max(-2., min(2., f - strongest)) + (word in words)
        for f, words in zip(frequencies, FUNCTION_WORDS)
    )

@lru_cache(None)
def fragment_response(token):
    word = token.strip().lower()
    french = zipf_frequency(word, 'fr') if word.isalpha() else 0.
    english = zipf_frequency(word, 'en') if word.isalpha() else 0.
    if word.endswith(('s', 't', 'd', 'x', 'z')):
        if french > 6:
            return .0593
        if english <= 1.5:
            return .1347
        if re.search(r'([bcdfgjklmnpqrstvwxz])\1', word):
            return -.1412
        return .4508 if english <= 6.5 else .887
    if french <= 3.5:
        return .0351
    if french > 6:
        return .0157
