        r'i(?:ce|er|est|es|or|ring|nger)|o(?:ci|ca|c|d|rd|ra|g[os]?|x)|'
        r'u(?:el|se[ds]?|rie[s]?|ra|zz|b)|ro[g]?|j)', tail
