    return (doc, (raw + b)[-512:], b), value

"""Sparse lexical responses, not one unified meaning.

Predict negative values for xi (Greek, spelled out, or in TeX), selected
backslash-led symbols, and Chinese do/play/manipulate verbs. A few following
letters continue the xi response. Dot leaders get a small positive value;
other text gets nearly zero. Two previous byte tokens handle split letters.
"""
READS = ()

# Do/mess with; manipulate; play; fish out; stir.
MANIPULATION = {
    "搞": -9.2,
    "弄": -6.4,
    "玩": -3.5,
    "捞": -4.0,
    "搅": -2.6,
    "弄得": -4.7,  # manipulate + result complement
}


def predict(token, previous, older):
    text = token.decode("utf-8", errors="replace")
    split = text.startswith("\ufffd")
    word = text.strip()
    if split:
        word = (older + previous + token).decode("utf-8", "replace")[-1:]
    if word in MANIPULATION:
        return MANIPULATION[word]
    if word in ("ξ", "Ξ"):
        return -8.8 if split else -5.8
    if text == "ι" and previous.endswith("ξ".encode()):
        return -3.1
    if text == "ς" and (older + previous).endswith("ξι".encode()):
        return -4.0
    if text == "i" and previous.endswith(b"x"):
        return -4.0 if previous.endswith(b"\\x") else -0.55
    if text == "\\x":
        return -2.05
    if text in ("\\xa", "\\xc", "\\xe"):
        return -0.32
    if previous.endswith(b"\\"):
        if text == "xi":
            return -5.3
        if text in ("overs", "stack"):  # overset and stackrel in TeX
            return -6.8
        if text == "x":
            return -2.2 if previous.endswith(b"\\\\") else -4.8
        if text in ("xa", "xc", "xe"):
            return -1.5
        if text in ("var", "v", "up", "s", "i"):
            return -1.6
    if word.lower() == "xi":
        return -1.3
    if text == "··":
        return 0.5
    return -0.002


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous = older = b""
    else:
        _, previous, older = carry
    token = prefix.token_bytes[-1]
    return (document, token, previous), predict(token, previous, older)

"""A local detector of opening syntax, not a complete parser.

Square brackets, slash-path openings, control-statement parentheses and C header
brackets give positive responses. Previous-token context distinguishes line
openings from word indexing. Extra rules cover NUL bytes, repeated middle dots,
a blank line after </think>, and a coarse document-initial response. We leave
most ordinary text at zero rather than learn a token-by-token lookup table.
"""
import re

READS = ()
CONTROL = {'if', 'while', 'for', 'foreach', 'switch', 'catch'}
PATH_OPENERS = frozenset("\"'([{: =")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    carry = (doc, token)
    text = token.strip()
    word = re.search(r'([A-Za-z]+)$', previous)
    word = word.group(1) if word else ''
    value = 0.0

    if token == '\x00':
        value = 0.15 if previous.isspace() else 1.9
    elif len(text) > 1 and set(text) == {'·'}:
        value = 0.67
    elif text.endswith(('[', '[\\')):
        if text.startswith(']'):
            value = 0.23
        elif previous.endswith('\\'):
            value = -0.3
        elif token[0].isspace():
            at_boundary = previous.isspace() or previous.endswith(':')
            value = 0.85 if at_boundary else 0.58
        elif text != '[':
            value = 0.75
        elif previous.endswith('\n'):
            value = 1.05
        elif previous and previous[-1].isalnum():
            value = 0.12
        else:
            value = 0.5
    elif text == '【':
        value = 0.65
    elif text in {'(', '(!', '($'} and word in CONTROL:
        value = 1.0 if word in {'if', 'while'} else 1.4
        if text == '(!':
            value *= 0.4
    elif text == '<' and word == 'include':
        value = 2.2 if previous.endswith('#include') else 1.5
    elif text.endswith('/') and all(c in PATH_OPENERS for c in text[:-1]):
        # A path opening, not // comments, XML closing tags, or ./.
        if text == ':/':
            value = 1.5
        elif any(c in text for c in "\"'"):
            value = 1.1
        elif token[0].isspace():
            value = 0.1 if previous[-1:].isdigit() else 0.6
            if previous.endswith(':'):
                value = 1.2
            elif word in {'cd', 'find', 'ls', 'cat'}:
                value = 0.95
        elif text == '/' and any(c in previous[-3:] for c in "\"'(#"):
            value = 1.2
        elif text != '/':
            value = 0.9
    elif text == 'from' and not token.startswith(' '):
        if previous.endswith(('\n', '\\n')) or token.startswith('\t'):
            value = 1.15
    elif token == '\n\n' and previous == '</think>':
        value = 0.26

    if not previous and value == 0:
        value = 0.38 if text.isnumeric() else 0.1
        if text in {'"', '“', "'", '‘'}:
            value = 1.3
    return carry, value

programs.haiku:
"""Component layers.1.mlp.down_proj:3223: the opener of a path, a condition, a list or an include.

What it does: it fires on a token that *opens* a new piece of code or shell text,
the point where a path, a condition, a list or a header name begins:
  * a path start: a "/" that begins an absolute path, mostly after a quote, colon,
    "=" or a word like `cd` (`cd /tests`, `rootdir: /workspace`, `"/src`, `PATH=/usr`).
    A "/" inside a path (`/src/x`) does not fire;
  * "(" right after a control keyword: `if (`, `for (`, `while (`, `catch (`,
    `switch (`, `foreach (`. A "(" after any other word (a call) does not fire;
  * "[" that opens a list, array or JSON value. It is strongest at the start of a
    line or after indentation, and weaker mid-line;
  * "<" right after `#include`, and "from" opening an import line;
  * a NUL character (as in UTF-16 text), a strong but rare case.
The first token of a row gets a small constant offset. Everything else predicts 0.

The prediction depends only on the newest token and the one before it (plus whether
it is the row's first token), so it is a simple stateless rule.
"""

READS = ()

# words after which an opening bracket or a path is expected
CONTROL = {"if", "for", "while", "catch", "switch", "foreach", "elif"}
# words after which a path begins
PATH_CUE = {"cd", ":", "include", "file", "of"}


def _core(tok):
    # the token without leading space and without any opening quote or bracket
    return tok.lstrip(" \t\"'`=:([{")


def step(carry, prefix, upstream):
    if len(prefix) == 1:
        return carry, 0.13  # first token of a row: small constant offset
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    p = prev.strip(" \t")  # the previous word or symbol
    line_start = "\n" in prev or prev.startswith("\t") or prev.startswith("  ")
    short = len(cur) <= 4 and "\n" not in cur

    if "\x00" in cur:
        return carry, 1.6
    if "<" in cur and p == "#include":
        return carry, 2.1
    if cur.strip(" \t") == "from" and line_start:
        return carry, 1.1
    # "/" that starts a path: a slash after a space, quote, colon or equals sign
    # (` /`, `"/`, `:/`, `="/`), or a bare slash right after a path cue
    if short and "/" in cur and not line_start and _core(cur) == "/":
        if cur[:1] != "/":
            return carry, 1.0
        if p in PATH_CUE:
            return carry, 0.9
        return carry, 0.0
    # "(" after a control keyword: a condition is opening
    if short and "(" in cur and not line_start:
        if p in CONTROL:
            return carry, 0.9
        return carry, 0.0
    # "[" opening a list or array
    if short and "[" in cur:
        if line_start:
            return carry, 0.85
        if p in CONTROL or p in PATH_CUE:
            return carry, 0.6
        return carry, 0.3
    return carry, 0.0

programs.sol:
"""A spelling-piece detector for the letter pairs gh and kh.

Strong negative responses mark small spelling pieces containing gh/kh, or
an h beginning a token immediately after g/k. Familiar English gh
spellings such as -igh and -ough are weak. The next piece of the same
word gets a smaller echo.
Common lowercase English words weaken a boundary match. A few familiar
spellings (Hugh names, lakh, hertz units) receive separate treatment.
The bh/dh/ph/jh spelling pieces have a weaker response. Arabic and Indic letters
named for kh/gh have their own response.
"""
import codecs
import re
import unicodedata
from wordfreq import zipf_frequency

READS = ()


def spelling(text, previous):
    s = text.strip().lower()
    p = previous.lower()
    joined = not text[:1].isspace()
    # Recognize hertz units before treating a split k-H as a digraph.
    if text.strip().endswith('Hz'):
        return 0.0
    if text[:1] not in 'hH' and s.strip(' ,.;:') == 'h':
        if p.strip(' ,.;:') == 'g':
            return -3.8
    if joined and p.strip() in ('bh', 'dh', 'ph', 'jh'):
        if s.isalpha() and len(s) <= 3:
            return -2.0 if s.startswith('h') else -1.1
    if joined and s.startswith('h') and p.endswith(('g', 'k')):
        n = len(s)
        if p.strip() in ('g', 'k') and n <= 4:
            if s == 'hi':
                return -1.0
            if p.endswith('k') and s == 'ho':
                return -2.8
            if n >= 3:
                if zipf_frequency(s, 'en') >= 4.7:
                    return -2.0
                return -6.5 if p.endswith('g') or n == 4 else -3.5
            return -8.0 if p.endswith('g') else -6.5
        if text[:1].isupper():
            return -2.0
        if (previous[:1].isspace() and previous.strip().islower()
                and len(p.strip()) >= 4
                and zipf_frequency(p.strip(), 'en') >= 4.2):
            return -1.5 if n <= 3 else -0.2
        if n >= 4:
            return -0.4
        if n == 1:
            return -8.0 if p.endswith('g') else -6.5
        if n == 2:
            if p.strip() == 'ng':
                return -2.2
            return -6.0 if p.endswith('g') else -4.5
        if p.endswith('ng'):
            return -1.5
        return -6.0 if p.endswith('g') else -2.8
    if 'kh' in s:
        if not s.isascii():
            return -0.1
        if len(s) == 2:
            return -4.8
        if s == 'lakh':  # the South Asian number word, one hundred thousand
            return -0.1
        if s.endswith('kh'):
            return -4.0 if len(s) <= 3 else -2.8
        if len(s) == 3:
            return -2.5 if s[-1] in 'aeou' else -0.5
        return -3.2 if len(s) == 4 else -0.1
    if 'gh' in s:
        if s == 'gh':
            if joined and p.endswith('n'):
                return -0.8
            if text.strip().isupper():
                return -1.5 if text[:1].isspace() else -2.7
            return -5.2 if text[:1].isspace() else -4.3
        if (p + s).endswith('laugh'):
            return -0.7
        if s.startswith('hugh'):
            return -4.7
        if s == 'igh':
            return -4.5 if text.strip().isupper() else -0.9
        # Familiar English gh clusters have little response.
        if re.search(r'igh|ough|augh', s):
            return -0.04
        if s.endswith('gh'):
            return -4.5 if len(s) <= 4 else -0.6
        if s.startswith('gh') and len(s) <= 4:
            return -1.5
        return -0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0.0, b'')
    _, previous, previous_value, pending = carry
    text = prefix.token_strings[-1]
    direct = spelling(text, previous)
    value = direct
    if not value and not text[:1].isspace() and text[:1].isalpha():
        if previous.lower().strip().endswith(('gh', 'kh')):
            value = 0.65 * previous_value
        else:
            value = (0.35 if len(text) <= 3 else 0.05) * previous_value
    data = pending + prefix.token_bytes[-1]
    decoded, used = codecs.utf_8_decode(data, 'ignore', False)
    pending = data[used:]
    for ch in decoded:
        name = unicodedata.name(ch, '')
        if name.endswith(('LETTER KHA', 'LETTER GHA')):
            value = direct = -5.0
        elif ch in 'خغ':
            value = direct = (-0.85 if len(decoded.strip()) == 1 else -0.2)
    return (doc, text, direct, pending), float(value)

"""A spelling-fragment approximation, centred on 'ter' and 'term'.

'Term(s)' gives the strongest negative response. The previous token can
weaken it (time-span adjectives, 'in terms') or strengthen it (numbers,
ordinals and listed mathematical modifiers). Short pieces completing
ter/term spellings across adjacent tokens also respond; long merged
words usually do not. Some cher/repeated-er fragments are positive.
Repeated doubled middle dots have a separate negative filler response.
ASCII transliteration makes the spelling tests case- and accent-insensitive.
"""
import re
from functools import lru_cache
from anyascii import anyascii

READS = ()
DETERMINERS = {'the', 'a', 'an', 'this', 'these', 'those', 'that'}
TIME_LENGTH = {'short', 'long', 'shorter', 'longer', 'medium', 'mid'}
ORDINALS = {'first', 'second', 'third', 'fourth', 'fifth', 'last', 'next', 'nth'}
QUANTITIES = {'all', 'both', 'two', 'three', 'four', 'five',
              'six', 'seven', 'eight', 'nine', 'ten'}
MATH_MODIFIERS = {'cross', 'boundary', 'constant', 'quadratic', 'cubic',
                  'linear', 'penalty', 'error', 'interaction', 'higher', 'order'}


@lru_cache(maxsize=65536)
def spelling(text):
    return anyascii(text).lower()


def predict(token, previous):
    s, p = spelling(token), spelling(previous)
    bare, before = s.strip(), p.strip()
    stem = bare.lstrip('_-.')
    if stem in {'term', 'terms'}:
        if bare.startswith('-') or before.rstrip('-') in TIME_LENGTH:
            return -1.04
        if stem == 'terms' and before == 'in':
            return -1.15
        if before in MATH_MODIFIERS or before in {'last', 'third'}:
            return -5.2
        if before in DETERMINERS:
            return -3.23
        if before in ORDINALS or before in QUANTITIES or before.isdigit():
            return -4.6
        return -3.7 if stem == 'term' else -3.4
    if bare in {'termed', 'termin', 'therm'}:
        return -1.8 if bare == 'termed' else -0.85
    if re.fullmatch(r'ter(?:r[ae]?|[ensy])?', bare) or bare == 'terry':
        return -1.8 if s.startswith(' ') else -0.6
    if bare in {'cher', 'chers', 'cherry'}:
        return 0.65
    if token == previous == '··':
        return -1.3
    if not s or not s[0].isalpha() or not p:
        return -0.002
    n = len(s)
    # Only pieces straddling the boundary count as spelling completions.
    for word in ('term', 'therm', 'ter', 'ther'):
        if any(p.endswith(word[:k]) and s.startswith(word[k:])
               for k in range(1, len(word))):
            if word == 'term':
                return (-6.0 if n == 1 else -4.0) if n <= 3 else -0.1
            if word == 'therm':
                return -3.5 / n if n <= 4 else -0.1
            if word == 'ter':
                return -1.05 if 2 <= n <= 4 else -0.05
            return -0.4 if n in (2, 3) else -0.1
    if p.endswith('ter'):
        if before == 'ter':
            return -3.0 / n if n <= 4 else -0.1
        if p.endswith('inter'):
            return -1.1 if n == 1 else -0.05
        return -1.3 * (4 - n) / 3 if n <= 3 else -0.05
    if p.endswith('term'):
        return -0.9 if n <= 3 else -0.1
    if p.endswith('er'):
        if s.startswith('m') and n <= 3:
            return -0.7 * (4 - n)
        if s == 'ich':
            return 3.0
        if s.startswith(('er', 're', 'ri')) and n <= 4:
            return 0.6
        if p.endswith('cher') and n <= 3:
            return 0.4
    if p.endswith('ch') and s.startswith(('er', 'ier')) and n <= 4:
        return 0.4 if n == 2 else 1.3
    return -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), predict(token, previous)

"""An L-cluster spelling detector, not a general meaning detector.

Lake/flake/blade/clue-like spellings tend positive; lui/gli/leur and
lah-like endings tend negative. A syllable split over tokens often has a
stronger response than the corresponding complete word. Only the newest
token and the previous token's spelling are used; documents reset state.
Numbers are approximate amplitudes estimated from training text.
"""
import re

READS = ()

# Onset before "ake": spaced word, unspaced piece, split after the onset.
AKE = {
    "l":  (2.6, 5.36, 5.0),
    "fl": (5.8, 7.5, 8.6),
    "bl": (5.55, 8.0, 15.1),
    "dr": (3.15, 5.0, 0.8),
    "br": (1.0, 2.0, 2.1),
}
# French/Italian pronouns, possessives, and article forms.
FUNCTION_WORDS = {
    "lui": -4.2, "leur": -2.1, "leurs": -0.7,
    "gli": -1.8, "agli": -2.8, "loro": -1.0,
}
# Complete tokens with related lateral-consonant spellings.
L_WORDS = {
    "clad": 3.2, "claude": 2.55, "claus": -2.25, "clause": 0.69,
    "slack": 0.96, "black": 0.12,
}
BLENDS = {"bl": 0.46, "cl": 0.12, "fl": 0.1,
          "lad": 0.48, "лад": 1.04}


def response(previous, token):
    p, s = previous.lower(), token.lower()
    w = s.strip()
    spaced = bool(s[:1].isspace())
    capital = 1.15 if spaced and token.strip()[:1].isupper() else 1.0

    if not spaced:
        if s == "li" and p.endswith("g") and not p.endswith("ng"):
            return -3.0
        if s == "ui" and p.endswith("l"):
            return -7.5 if p.strip() in ("l", "-l") else -2.8
        if p.endswith("l") and s == "ah":
            return -3.0
        if p.endswith(("il", "ul")) and s == "h":
            return -3.1
        if p.endswith("gl") and (s == "u" or s.startswith("ut")):
            return -1.5
        if re.fullmatch(r"ake[nsr]?", s):
            for onset in ("bl", "fl", "l", "br", "r"):
                if p.endswith(onset):
                    return AKE.get(onset, AKE["dr"])[2]
        if p.endswith("l"):
            if re.fullmatch(r"ade[dsr]?", s):
                return 6.2 if p.endswith(("bl", "cl")) else 3.8
            if s.startswith("ad"):
                return 0.7
            if s.startswith("ack"):
                return 2.4
            if re.fullmatch(r"aze[ds]?|azing", s):
                return 1.9 if s.endswith("ing") else 4.0
            if p.endswith(("bl", "cl", "fl")) and s in ("ue", "ues", "uest"):
                return 3.5
        if p.endswith("cla") and s.startswith("ude"):
            return 5.5

    m = re.fullmatch(r"(l|fl|bl|dr|br)ake(s)?", w)
    if m:
        value = AKE[m[1]][0 if spaced else 1]
        return value * capital * (0.5 if m[2] else 1.0)
    if re.fullmatch(r"blade(s)?", w):
        return 3.3 * capital * (1 if spaced else 1.6) * (
            0.47 if w.endswith("s") else 1)
    if re.fullmatch(r"clue(s)?", w):
        return 3.4 * capital * (0.45 if w.endswith("s") else 1)
    if w in FUNCTION_WORDS:
        factor = 0.5 if not spaced and w in ("leur", "gli") else 1
        return FUNCTION_WORDS[w] * factor
    if w.endswith("lah") and 3 <= len(w) < 8:
        return -4.0 / (len(w) - 2)
    if w == "aille":
        return -1.3
    if re.fullmatch(r"clar(?:k(?:e)?|a)", w):
        return 1.6 * capital
    if re.fullmatch(r"[bg]laz(?:e|ed|es|ing)", w):
        return 1.9 * capital
    return L_WORDS.get(w, BLENDS.get(w, 0.0)) * capital


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    return (doc, token), float(response(previous, token))

programs.haiku:
"""layers.1.mlp.down_proj:3227 -- a "citation / web-reference" unit with a small biographical counterweight.

What it does, in plain terms: this component is mostly quiet. It turns negative when the text is
pointing at a written source, and it turns mildly positive on encyclopedic person/place facts.

  * Start of a document (first token after a document boundary): a mild negative value.
  * The " al" of "et al." right after " et": strongly negative (author citation).
  * Web addresses and URL pieces ("www", "http", "https", "://", ".html", "docs"): strongly negative.
  * Weaker web/source words ("website", "site", "blog", ".org", ".com", ...): mildly negative.
  * Scholarly and publication words ("Dr", "Jr", "Inc", "book", "paper", "article", "reported",
    "published", "authors", "titled", ...): moderately negative.
  * " country" (as in "... country of citizenship"): positive, as are biographical/place words
    ("located", "died", "football", "politician", "County", "-old", ...): mildly positive.
  * Everything else: 0.

The values are rough averages of the component's activation on those tokens, read off training
rows. The lists are the concept; the numbers are only their typical sizes.
"""

READS = ()

DOC_START = -0.27
ET_AL = -1.5
WEB_STRONG = {"www", " www", "http", " http", "https", " https", "://", ".html", ".htm", "docs", "/latest", "/wiki", "/en"}
WEB_WEAK = {" website", "website", " websites", " site", " blog", "github", ".org", ".com", " documentation", ".pdf"}
SCHOLARLY = {" et", " Dr", "Dr", " Jr", " Inc", " Co", " Corp", " Vol", " vol", " eds", " ed", " Edition", " Journal",
             ".,", " book", " books", " paper", " article", " articles", " report", " Report", " research", " Research",
             " standard", " specification", " spec", " textbook", " literature", " authors", " author", " researchers",
             " writes", " wrote", " argues", " recommend", " reported", " published", " proposed", " released",
             " announced", " titled", " entitled"}
BIOGRAPHY = {" located", " County", " died", " football", " politician", " junior", " Northern",
             " Central", " South", " foreign", " certain", " Since", "-old", " Library", " History", " called"}
US_NAMES = {" United", " US", ".S", " York", " Act", " No", " Pat", " Nos"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, DOC_START
    if tok == " al" and prefix.token_strings[-2] == " et":
        return None, ET_AL
    if tok in WEB_STRONG:
        return None, -0.9
    if tok in WEB_WEAK:
        return None, -0.3
    if tok in SCHOLARLY:
        return None, -0.35
    if tok == " country":
        return None, 0.6
    if tok in BIOGRAPHY:
        return None, 0.3
    if tok in US_NAMES:
        return None, -0.25
    if tok == " by":
        return None, -0.12
    return None, 0.0

programs.sol:
"""Approximate a sparse collection of lexical and document-opening responses.

Strong positive guesses cover initial docstrings/comments, function starters,
reasoning tags, and two Italian classified-advertising site names. Import/export
starters and doubled middle dots are negative. At document starts, case,
spacing, and script supply coarse background estimates. Otherwise use 0.002.
This deliberately leaves most token-specific variation unexplained.
"""

import regex

READS = ()

# Message-format markers: (document-initial value, other-position value).
MARKERS = {
    '<think>': (0.535, 0.535),
    '</think>': (0.086, 0.086),
    '<tool_response>': (0.185, 0.185),
    '</tool_response>': (0.185, 0.185),
    '<tool_call>': (-0.078, -0.078),
    '</tool_call>': (0.040, 0.040),
    '<|im_end|>': (0.047, 0.047),
    '<|im_start|>': (0.324, 0.022),
    '<|endoftext|>': (1.66, -0.011),
}


def activation(s, first):
    q = s.strip()
    if q in MARKERS:
        return MARKERS[q][0 if first else 1]
    if q == '··':
        return -0.59
    if q in ('bakeka', 'vivastreet'):
        return 1.05 if q == 'bakeka' else 0.80
    if not first:
        return 0.002

    if q in ("'''", '"""'):
        return 2.18 if q[0] == "'" else 1.26
    if q.startswith('/*'):
        return 1.04 if '\n' in s else 0.71
    if s == 'void':
        return 2.0
    if s == ' .':
        return -1.93
    if s in ('using', 'export'):
        return -1.5
    if s == 'import':
        return -0.49
    if s in ('def', 'function'):
        return 0.70
    if s in ('int', 'float', 'double', 'char', 'bool'):
        return 0.59
    if q and set(q) == {'#'}:
        return 0.66 / len(q)
    if regex.fullmatch(r'\p{Script=Hangul}+', q):
        return -0.65
    if regex.fullmatch(r'\p{Script=Thai}+', q):
        return -0.75
    if s == 'The':                 # Capitalized definite article, without a space.
        return 0.70
    if q.isascii() and q.isalpha() and q[0].isupper():
        return 0.28 if not s[0].isspace() else -0.06
    if s.isspace():
        if s == ' ':
            return 0.40
        return 0.25 if '\n' in s or '\t' in s else 0.10
    if q.isascii() and q.isalpha() and not s[0].isspace():
        return -0.15 if len(q) == 1 else 0.11
    return 0.06


def step(carry, prefix, upstream):
    first = (len(prefix.document_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    return None, activation(prefix.token_strings[-1], first)

