"""Document-start rule: at the first token of a document, the activation is a fixed value
per token, roughly by kind of token. Plus two chat-format markers."""

READS = ()

OPENERS = ("#", "//", "/*", "--", '"""', "'''")
CODE_WORDS = ("using", "export", "import", "#include", "const", "#![", "'use", "use")


def is_start(prefix):
    return len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]


def start_value(s):
    core = s.strip()
    if s.startswith("<|") or s.startswith("<think") or s.startswith("<tool"):
        return 0.3
    if core == "" or "�" in s:
        return 0.3 if core == "" else 0.0
    if s.startswith(OPENERS):
        return 0.7
    if s in CODE_WORDS:
        return -0.3
    if sum(ord(c) > 127 for c in s) * 2 >= len(s):
        return 0.0
    if core.isalpha():
        return 0.28 if core[0].isupper() else 0.05
    return 0.1


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s == "<think>":
        return None, 0.55
    if s in ("<tool_response>", "</tool_response>"):
        return None, 0.18
    if is_start(prefix):
        return None, start_value(s)
    return None, 0.0

