import regex as re

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', b'')
    _, last_word, last_token, tail = carry
    word = raw.strip()
    lower = word.lower()

    # Follow a spelling across token boundaries, not across spaces.
    joined = last_word + raw
    match = re.search(r'\p{Script=Latin}+\Z', joined)
    spelling = match.group().lower() if match else ''
