    root = ('north', 'nord', 'norte', 'nörd')
    split_root = (continuation and last_word
                  and (spelling.startswith(root) or spelling == 'nort')
                  and not (last_word.lower().startswith(root)
                           or last_word.lower() == 'nort'))

    value = 0.0
    if split_root:
        if spelling.startswith('nörd'):
            value = 4.5
        elif spelling.startswith(('northeast', 'northwest')):
            value = 3.5
        else:
            value = 14.0 if lower in {'orte', 'ther', 'thern'} else 12.0
    elif lower == 'north':
        if word.isupper():
            value = 9.5
        elif word[0].isupper():
            value = 7.9 if raw[0].isspace() else 6.2
        else:
            value = 6.7 if raw[0].isspace() else 8.0
        if last_token.lower().strip() == 'the':
            value += 1.1
    elif lower == 'northern':
        value = 6.4 if raw[0].isspace() else 8.6
    elif lower.startswith('nörd'):
        value = 4.5
    elif lower in {'nord', 'norte'}:
        value = 10.4 if word == 'nord' else 7.2
    elif lower.startswith(('northeast', 'northwest')):
        value = 3.0
    elif lower == 'nordic':
        value = 2.0
    elif lower == 'beijing':
        value = 1.8

    # Recover a completed Han character from at most two preceding bytes.
    data = tail + prefix.token_bytes[-1]
