            value = 3.7
        elif lower.lstrip('-') in {'east', 'west', 'eastern', 'western'}:
            value = 2.7
        elif lower in {'america', 'american', 'korea', 'korean', 'vietnamese'}:
            value = 2.6
    elif previous == 'northern' and lower in {'ireland', 'irish'}:
        value = 1.9

