BLOCK_VALUES = {
    'Runic': 3.0,
    'Enclosed_Alphanumeric_Supplement': 2.9,
    'Mathematical_Alphanumeric_Symbols': 2.5,
    'Miscellaneous_Symbols_And_Pictographs': 3.1,
    'Supplemental_Symbols_And_Pictographs': 3.5,
    'Transport_And_Map_Symbols': 0.9,
    'Enclosed_Alphanumerics': 3.0,
    'Supplemental_Mathematical_Operators': 1.3,
    'Greek_Extended': 0.25,
