BLOCKS = [(name, regex.compile(r'\p{Block=' + name + '}'), value)
          for name, value in BLOCK_VALUES.items()]


def unfinished(data):
    """The incomplete UTF-8 character at the end, if any."""
    for i in range(len(data) - 1, max(-1, len(data) - 5), -1):
        x = data[i]
        if x < 128:
            return b''
        if x >= 192:
            width = 2 if x < 224 else 3 if x < 240 else 4
            return data[i:] if len(data) - i < width else b''
    return b''


