        elif text == r'\n':
            value = -2.16
        elif text == r'\s':
            value = -1.74
        elif text == 'using':
            value = 1.63
        elif text in ('package', '#include'):
            value = 0.65
        elif text.isspace():
            value = -0.3
        elif text == 'To':
            value = 1.94
        elif text == ' .':
            value = -2.41
        elif text == ' to':
            value = 0.61
        elif text == ' a':
            value = -0.65
        elif text.strip().isdigit():
            value = -0.33
        elif text.startswith(' ') and text.strip().islower():
            value = -0.3
        opening = text in (r'\t', r'\n', r'\s')
    if tail and not (continuation and pending):
        spaced = joined[:-len(tail)].endswith(b' ')
