GERMAN = frozenset(
    """der die das den dem des ein eine einen einem einer und ist nicht ich du er sie es
    wir ihr mit für auf von zu im auch noch sich wird wurde werden kann können hat haben
    war sind sein dass daß als oder aber doch nur schon sehr wie wenn dann dort hier viel
    mehr zum zur vom ohne unter über vor gegen durch bei nach aus ihre ihren ihrer ihm ihn
    gerne sehen familie jahre mit ich heeft naar niet het een zijn ook maar van dat ik""".split()
)
NAMES = frozenset(
    """John Paul Jim Jimmy Don Ron Tom Bob Mike Michael Mary James Jeff Kim Ian Luke Roger
    Louis Tim Alex Rob Jon Jean Mel Marc Vin Dave Gary Bill Joe Steve Ed Ce Cl Cle Clo Car
    Bo Jo Luc Tem Vo Tor Lo Ch Le La Nic Ro Na Mark Mc Mac Jul""".split()
)
