def is_german(token):
    word = token.strip()
    if any(ch in "äöüßÄÖÜ" for ch in token):
        return True
    if word.lower() in {w.lower() for w in GERMAN}:
        return True
    return word.isalpha() and len(word) >= 5 and word.endswith(GERMAN_SUFFIXES)


