    """The component's value at a segment's first token, from that token alone."""
    if is_german(token):
        return -8.0
    word = token.strip()
    if token.startswith("<|"):
        return 2.6
    if word == "":
        return 0.0
    if token.isdigit():
        return -1.0
    if not any(ch.isalnum() for ch in word):
        return 0.0
    script = script_of(token)
    if script in ("CYRILLIC", "ARABIC", "KATAKANA"):
        return 4.0
    if script == "HANGUL":
        return -2.0
    if script in ("CJK", "HIRAGANA", "THAI", "IDEOGRAPHIC"):
        return 1.5
    if script != "LATIN":
        return 1.0
    if word in NAMES:
        return 8.0
