    """Called at every position. A segment starts at position 0 of a row, or where the
    document id changes. Elsewhere the component predicts 0."""
    starts_segment = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_segment:
        return None, 0.0
    return None, float(value_of(prefix.token_strings[-1]))

