INTRODUCTIONS = {
    'thus', 'so', 'therefore', 'yes', 'similarly', 'alternatively',
    'wait', 'then', 'first', 'however', 'hence', 'finally', 'now',
}


def unpacking(line, terminator):
    if terminator not in ('=', ':=', 'in'):
        return False
    if terminator == 'in':
        match = LOOP.search(line)
        if not match:
            return False
        before = line[:match.start()]
        return bool(re.fullmatch(r'\s*[+-]?\s*(?:\d+\s+)?', before)
                    or any(c in before for c in '=[{'))
    first = re.search(r'[A-Za-z_]+', line)
