        age += 1

    comma = ',' in s or '、' in s
    closed = False
    gain = -2.70 if comma else 0.0
    if not any(c in t for c in '([{'):
        for chars, weight in [(')）', 4.56), (']】', 2.98),
                              ('}', 3.84), ('>⟩', 3.22)]:
