        gain = 0.90
    if t in ('=', ':='):
        gain = 3.39
    elif t in ('等', 'etc', 'etc.'):
        gain = 0.17
    elif t == '.':
        gain = 0.61
    elif t == '+':
        gain = 2.11
    elif t in ('—', '–', '-'):
        gain = 0.21

    value = 0.0
