                    - 0.103 * sum(c.isspace() for c in gap)
                    - 1.71 * sum(c in '()[]{};\n=' for c in gap) + boost)
        if closed:
            exponent -= 0.84 * max(len(t) - 1, 0) + 0.88 * ('\n' in s)
        value = gain * math.exp(max(-30, min(4, exponent)))
        if comma and any(c.isalpha() for c in t) and not closed:
