        elif previous == 'the':
            value = 6.9
        elif previous == 'not':
            value = 4.0
        else:
            value = 5.1
    elif word == 'most':
        if token.strip().isupper():
            value = 0.65
        elif token.strip() == 'Most':
            value = 0.12
        elif previous in ARTICLES | POSSESSIVES | {'single', 'very'}:
            value = 0.98
        elif previous in COPULAS | {'and', 'but', 'you'}:
            value = 0.5
        else:
            value = 0.08
    elif word == 'less':
        if not token[:1].isspace() and token == 'less':
            value = 0.15  # Usually the suffix in a word such as 'careless'.
        elif previous in ARTICLES:
            value = 1.8
        elif previous in {'in', 'of', 'with', 'and'}:
            value = 1.4
        elif previous in {'much', 'far', 'or', 'many'}:
            value = 0.35
        else:
            value = 0.75
    elif word == 'lesser':
        value = 1.8
    elif word == 'more':
        if token.strip() == 'More':
            value = 0.13
        elif previous in COPULAS:
            value = 0.48
        elif previous in {'read', 'learn', 'see', 'one', 'have'}:
            value = 0.02
        else:
            value = 0.24
    elif word in {'plus', 'mais', 'moins'}:
        words = re.findall(r"[^\W\d_]+", tail.lower())
        french = sum(w in FRENCH for w in words)
        if word == 'plus':
            english = sum(w in ENGLISH for w in words)
            value = 0.75 if french > english else 0.15
        elif word == 'mais':
            portuguese = sum(w in PORTUGUESE for w in words)
            value = 0.9 if portuguese > french else -0.08
        else:
            value = 3.0 if previous in {'le', 'la', 'les'} else 1.0
            if previous in {'au', 'du'}:
                value = 0.1
    elif word == 'más':
        value = 0.76
    elif word == 'menos':
        value = 0.42
    elif word in {'più', 'meno', 'meer'}:
        value = 0.25

    # The two mathematical abbreviations also express a minimum.
    joined = token.strip()
    if previous:
        joined = (prefix.token_strings[-2] + token).strip()
    if token.strip() == 'LSB' or joined == 'LSB':
        value = 4.5 if token.strip() == 'LSB' else 7.0
    elif word == 'lcm' or joined == 'LCM':
        value = 2.4 if joined == 'LCM' else 1.3
    elif word.startswith('lease'):
        value = 1.2
    elif tail and tail[-1].isalpha():
        value += fragment_response(previous, token)

    return (doc, (tail + token)[-200:], word), value

programs.haiku:
"""Degree words: "the least", "less", "the most", "more"; a document-start dip.

What the component responds to: words that express a degree comparison,
chiefly the superlative "least" in "the least count", "the least bit", and
"less"/"lesser" in "a less severe", "the lesser of". "lest" also fires, and
"most" when it is a superlative after a determiner ("the most common").
It is near zero on the idiom "at least" and on quantifier uses of "most"
("most of", "most people"). "more", "plus" and the French/Spanish "más"
fire weakly. Elsewhere it is near zero.

The first token of each document (the model resets there) gets a fixed
negative value, the average the component takes at document starts.
"""

READS = ()

LEAST = {" least", " Least", "least", "Least", " lest", "lest"}
LESS = {" less", " Less", "less", "Less", " lesser", "lesser"}
MOST = {" most", " Most", " MOST", "most", "MOST"}
WEAK = {" more", " plus", " más", " moins", " mais", "more"}
DETERMINERS = {" the", " The", " their", " his", " its", " my", " our", " your"}
IDIOM_BEFORE_LEAST = {" at", " At"}
DOC_START = -0.3


def step(carry, prefix, upstream):
    # Each document restarts the model's positions, so its first token is special.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, DOC_START
    word = prefix.token_strings[-1]
    before = prefix.token_strings[-2]
    if word in LEAST:
        return carry, 0.0 if before in IDIOM_BEFORE_LEAST else 5.0
    if word in LESS:
        return carry, 1.0
    if word in MOST:
        return carry, 1.0 if before in DETERMINERS else 0.0
    if word in WEAK:
        return carry, 0.3
    return carry, 0.0

programs.sol:
"""A sparse code-opening signal with a small typographic background.

At document starts, PHP/HTML openers and public declarations have sharp,
syntax-specific responses. Comments and triple-quoted strings are positive;
import/package declarations, a chat opener, and a leading NUL are negative.
Isolated Latin letters are suppressed initially; later, capital initials and
conversation delimiters have small responses. Everything else is near zero.
This is an approximation,
not a description of all the component's token-specific variation.
"""
READS = ()

# Recognizable source-file and conversation opening tokens.
OPENERS = {
    'public': 1.605,
    '<!': 2.010,
    '<?': 0.238,
    'import': -0.315,
    'package': -0.499,
    '<|im_start|>': -0.413,
    '#': -0.346,
    '\x00': -2.797,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, previous = 0, ''
    else:
        _, pos, previous = carry
    token = prefix.token_strings[-1]
    stripped = token.strip()
    latin_letter = (len(stripped) == 1 and stripped.isascii()
                    and stripped.isalpha())
    value = 0.002

    if pos == 0:
        if token in OPENERS:
            value = OPENERS[token]
        elif token.startswith('/*'):
            value = 0.6 if '\n' in token else 0.4
        elif token.startswith(('"""', "'''")):
            value = 1.03 if '\n' in token else 0.6
        elif latin_letter:
            value = -0.26
    elif pos == 1 and previous == '<?' and token == 'php':
        value = -1.370
    elif pos == 1 and previous == '<!' and token == 'DOCTYPE':
        value = -0.276
    elif pos == 2 and previous == 'DOCTYPE' and token == ' html':
        value = -0.321
    elif pos == 1 and previous == 'public' and token == ' class':
        value = -0.187
    elif token == '<|im_end|>' or token == '</tool_response>':
        value = 0.059
    elif token == '<tool_call>':
        value = -0.066
    elif token == '</tool_call>':
        value = -0.093
    elif token == '<think>':
        value = 0.072
    elif token == '</think>':
        value = 0.045
    elif token.startswith(' ') and latin_letter:
        value = 0.034 if stripped.isupper() else 0.007
    return (doc, pos + 1, token), value

"""Approximate feature/feather vocabulary, related characters, and start effects.

The main response is to 'feature' and 'feather', including identifiers.
There are weaker trait/characteristic responses, spelling side-responses,
and suppression at document starts.  A short tail joins split words and
UTF-8 characters; it is cleared at each new document.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = b''
    else:
        tail = carry[1]
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    joined = (tail + raw).decode('utf-8', 'ignore')
    low = token.lower()
    value = 0.0

    # The same stem in prose, headings, and code identifiers.
    m = re.search(r'featur(e[sd]?|ing)$', joined.lower())
    if m:
        value = 2.1 if m.group(1) == 'e' else 1.5
        if not token[:1].isspace():
            value += 1.0
    elif low.strip() in ('trait', 'traits'):
        value = 1.0 if low.strip() == 'trait' else 0.55
    elif low.strip() in ('characteristic', 'characteristics'):
        value = 0.3
    elif low.strip() == 'feat':
        value = 0.9

    # The similar spelling 'feather' produces an even larger response.
    if re.search(r'feather(s|ed)?$', joined.lower()):
        value = 2.9 if joined.lower().endswith('feathers') else 5.0
        if low == 'ather':
            value = 8.0

    # Two spelling side-responses on subword continuations.
    before = tail.decode('utf-8', 'ignore').lower()
    if low == 'cker' and before.endswith(('e', 'ä')):
        value = 1.5
    if low.startswith('ch') and re.search(r'(?:^|\W)fe$', before):
        value = -4.5

    # 徴 (Japanese), 徵 (traditional), 征 (simplified).
    if joined.endswith(('徴', '徵', '征')):
        value = 5.8 if len(token.strip()) <= 1 else 2.3
    elif token == '징':
        value = 3.2

    # The first token is generally suppressed, especially code openers.
    if not tail:
        value -= 0.2
        if token == '#include':
            value = -2.5
        elif token.startswith('//'):
            value = -4.6 if '\n' in token else -2.1

    # A run of middle dots is another strong, negative spelling response.
    if token == '··' and tail.endswith('·'.encode()):
        value = -4.35
    return (doc, (tail + raw)[-32:]), value

"""Detect the spelling e-i, especially when i starts a short continuation.

The response depends on the continuation's consonants, length, script and
case. A complete, common German word containing ei is usually much weaker
than a short syllable. Transliteration lets the same rule cover related
vowel sequences in Greek, Cyrillic, Korean and Japanese katakana. Chinese
readings are not treated as literal spellings. A response can persist onto
the next Greek letter or archaic long s. Documents reset the state.
"""
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency
import regex

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    raw = text.strip()
    han = bool(regex.search(r'\p{Script=Han}', raw))
    word = raw.lower() if han else anyascii(raw).lower()
    latin = bool(regex.search(r'\p{Script=Latin}', raw))
    return raw, word, latin


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    raw, word, latin = spelling(text)
    previous = ''
    prev_raw = ''
    previous_ei = False
    if carry is not None and carry[0] == doc:
        _, previous, prev_raw, previous_ei = carry
    value = 0.0
    joined = previous.endswith('e') and word.startswith('i')
    ends_ei = word.endswith('ei') or (joined and word == 'i'
                                    and not text[:1].isspace())
    state = doc, word, raw, ends_ei
    if joined and not text[:1].isspace():
        if latin:
            tail = word[1:]
            if not tail:
                value = 7.0 if raw.isupper() and prev_raw.isupper() else 4.3
                if raw.lower() != 'i':
                    value *= 0.4
                if len(previous) > 4:
                    value *= 0.5
            elif tail.startswith(('ss', 'sh')):
                value = 6.3 if len(word) <= 3 else 1.6
            elif len(previous) > 3:
                value = 0.15
            elif tail.startswith('d'):
                value = 3.2
            elif tail[0] in 'bp':  # bilabial stops
                value = 2.3
            elif tail.startswith('e'):
                value = 2.8
            elif tail[0] in 'ckq':  # spellings of a velar stop
                value = 1.6
            elif tail.startswith('s'):
                value = 2.0 / max(1, len(tail))
            else:
                value = 0.4
        elif regex.search(r'\p{Script=Greek}|\p{Script=Cyrillic}', raw):
            value = 1.0
        elif word == 'i' and regex.search(
                r'\p{Script=Katakana}|\p{Script=Hangul}', raw):
            value = 5.5 if previous == 'e' else 2.0
    elif latin and 'ei' in word:
        tail = word.split('ei', 1)[1]
        if not tail:
            common = zipf_frequency(word, 'de') > 5.7
            if common:
                if text.startswith(' '):
                    value = 0.25
                else:
                    value = 1.5 if raw.istitle() else 4.4
            elif len(word) > 4 and not raw.istitle():
                value = 0.3
            else:
                value = 1.1 if zipf_frequency(word, 'it') > 6 else 3.2
        elif tail in ('ss', 'sh'):
            value = 4.8 if raw.istitle() else 1.5
        elif tail.startswith('d') and len(word) <= 5:
            value = 4.0 if raw.istitle() else 2.0
        elif word.startswith('ei') and raw.istitle() and len(word) > 4:
            value = 1.2
        elif len(word) <= 4:
            value = 0.3
    elif previous_ei and not text[:1].isspace():
        if raw == 'ſ':
            value = 3.0
        elif regex.search(r'\p{Script=Greek}', raw):
            value = 0.7
    return state, float(value)

"""Spanish lexical context, especially short words and word fragments.

Dictionary frequencies in Spanish, English, Portuguese, French, Italian and
German supply language evidence. Completed words update a decaying language
history; prefix frequencies let an unfinished word supply evidence too.
The small rules below map Spanish confidence, word length and frequency to a
negative activation. Nonletters usually contribute little. Document starts
have a separate, coarse negative offset. This is not a token-ID lookup.
"""
import math
import re
from functools import lru_cache
from wordfreq import top_n_list, zipf_frequency

READS = ()
LANGUAGES = ('es', 'en', 'pt', 'fr', 'it', 'de')
LATIN_WORD = re.compile(r'[A-Za-zÁÉÍÓÚÜÑáéíóúüñÀ-ÿ]+')

# Sum the frequencies of dictionary words beginning with each prefix.
PREFIX_FREQUENCIES = []
for language in LANGUAGES:
    counts = {}
    for word in top_n_list(language, 40000):
        if not LATIN_WORD.fullmatch(word):
            continue
        frequency = 10 ** (zipf_frequency(word, language) - 6)
        for length in range(1, min(len(word), 18) + 1):
            beginning = word[:length]
            counts[beginning] = counts.get(beginning, 0.) + frequency
    PREFIX_FREQUENCIES.append(counts)


@lru_cache(maxsize=100000)
def language_evidence(word, unfinished=False):
    word = word.lower()
    if not word or not LATIN_WORD.fullmatch(word):
        return (0.,) * 6
    if unfinished:
        scores = [math.log10(max(.003, d.get(word, 0.)))
                  for d in PREFIX_FREQUENCIES]
    else:
        scores = [max(2.5, zipf_frequency(word, language)) - 6
                  for language in LANGUAGES]
    mean = sum(scores) / 6
    return tuple(s - mean for s in scores)


def spanish_confidence(scores):
    scores = [s * 2.3 for s in scores]
    scores[1] += 2.5  # English is a more common default than Spanish.
    largest = max(scores)
    weights = [math.exp(s - largest) for s in scores]
    return weights[0] / sum(weights)


def remember(history, word):
    return tuple(.65 * old + new for old, new in
                 zip(history, language_evidence(word)))


def activation(confidence, token_confidence, prefix_confidence,
               word_length, word_frequency, token_frequency,
               letters, leading_space, start):
    if confidence <= .79:
        if start:
            return -.30
        if confidence <= .30:
            return -.0037
        if not word_frequency:
            return -.036
        return -.20 if confidence <= .48 else -.48
    if not letters:
        return -.076
    if word_length > 6:
        return -.77
    if token_confidence > .43:
        if prefix_confidence <= .12:
            return -1.44
        if word_frequency > 7.45:
            return -.41
        return -1.28 if token_frequency > 7.44 else -.82
    if confidence <= .97:
        return -1.12 if leading_space else -.74
    if word_length > 4:
        return -1.07
    return -1.44 if token_frequency <= 5.13 else -1.20


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != document
    if start:
        word, history = '', (0.,) * 6
    else:
        _, word, history = carry

    if not token[:1].isalpha() and word:
        history = remember(history, word)
        word = ''
    special = token.startswith('<|') and token.endswith('|>')
    matches = [] if special else list(LATIN_WORD.finditer(token))
    fragment = matches[-1].group() if matches else ''
    if matches:
        if len(matches) > 1 or matches[0].start() > 0:
            word = fragment
        else:
            word += fragment
    else:
        word = ''
    word = word[-40:]

    evidence = language_evidence(word, unfinished=True)
    confidence = spanish_confidence(tuple(
        .7 * old + new for old, new in zip(history, evidence)))
    value = activation(
        confidence,
        spanish_confidence(language_evidence(fragment)),
        spanish_confidence(language_evidence(fragment, unfinished=True)),
        len(word), zipf_frequency(word.lower(), 'es') if word else 0.,
        zipf_frequency(fragment.lower(), 'es') if fragment else 0.,
        bool(fragment), token[:1].isspace(), start)
    if token.endswith((' ', '\n', '\t')) and word:
        history = remember(history, word)
        word = ''
    return (document, word, history), value

"""Underscore notation, chiefly numbered placeholder names and mathematical bounds.

A placeholder's underscore has a large negative response, and its following
numeric index a smaller one. Identifier separators and C type suffixes are negative
too. Subscripts on norms and large mathematical operators are positive.
Bar-adjacent exponents and bounds can also be positive. Weak lexical effects
are left out. Document boundaries reset the two-token memory.
"""
READS = ()

# Responses on: a separate underscore, a combined subscript opener,
# and the first digit or brace following a separate underscore.
MATH = {
    'norm': (12.0, 13.4, 13.6),
    'limits': (3.9, 8.0, 4.6),
    'large operator': (3.3, 6.1, 4.8),
    'sum or product': (2.8, 4.3, 5.5),
    'other operator': (2.7, 2.8, 4.3),
    'bracket': (0.15, 9.3, 4.0),
    'closed group': (1.0, 2.6, 0.2),
    'square bracket': (5.5, 9.8, 5.0),
    'set or tensor operator': (4.0, 7.8, 5.5),
    'integral sign': (7.0, 7.6, 6.6),
}


def operator(s):
    raw = s
    s = s.strip()
    if raw != s and s in {'int', 'min', 'max', 'vert'}:
        return None
    if s.endswith('|') or s in {'Vert', 'vert', '∥', '‖', '∣'}:
        return 'norm'
    if s.endswith('>') or s in {'rangle', '⟩'}:
        return 'bracket'
    if s in {'∫', '∮', '∯', '∰'}:
        return 'integral sign'
    if s in {'cup', 'cap', 'bigcup', 'bigcap', 'otimes', 'imes', 'oplus'}:
        return 'set or tensor operator'
    if s in {'limits', 'imits'}:
        return 'limits'
    if s in {'int', 'iint', 'oint', 'lim', 'sup', 'inf', 'min', 'max'}:
        return 'large operator'
    if s.lower() in {'sum', 'prod', '∑', '∏'}:
        return 'sum or product'
    if s in {'times', 'partial', 'nabla', 'ord'}:
        return 'other operator'
    if s.endswith(']'):
        return 'square bracket'
    if s.endswith('}'):
        return 'closed group'
    return None


def base(s):
    word = s.strip().lstrip('.(')
    if word == 'username':
        return 'user placeholder'
    if word in {'param', 'func'}:
        return 'code placeholder'
    if word == 'NAME':
        return 'spaced name' if s.startswith(' ') else 'name'
    word = word.lstrip('_')
    if word in {'UTF', 'LABEL'}:
        return 'code placeholder'
    if s.isdecimal():
        return 'number'
    if len(word) == 1 and word.isalpha():
        return 'variable'
    if len(word) > 1 and word.isupper():
        return 'constant'
    if len(word) > 1 and word.isalpha():
        return 'word'
    return 'other'


def response(s, p, pp):
    k = base(p)
    op = operator(p)
    if s.strip() == '_':
        if op:
            if op == 'norm' and p.startswith(' ') and p.strip() in {'|', '||'}:
                return 2.0 if p.strip() == '||' else 3.5
            if op == 'square bracket' and s != '_':
                return 0.0
            return MATH[op][0]
        if s != '_':
            return 0.65 if p == s else 0.0
        return {'spaced name': -12.1, 'name': -8.9, 'number': -3.1,
                'constant': -4.0, 'word': -1.55, 'variable': -0.9,
                'user placeholder': -15.8, 'code placeholder': -9.8}.get(k, 0.3)
    if s.startswith(('_{', '_(', '_\\')):
        return MATH[op][1] if op else 0.47
    if s == '_t':
        stem = p.strip().lstrip('(.')
        if k == 'number':
            return -4.5
        if stem in {'Float', 'Double', 'Option', 'Int', 'UInt', 'Bool',
                    'float', 'double'}:
            return -6.5
        if stem.lower() in {'size', 'ssize', 'time', 'clock', 'ptrdiff',
                            'intptr', 'uintptr', 'wchar', 'off', 'pid'}:
            return -3.0
        if k in {'word', 'constant'}:
            return -4.3 if stem[:1].isupper() else -2.4
        return -0.4
    if s.startswith('}_'):
        return 9.6 if op == 'norm' else 1.2
    if op == 'norm' and len(s) == 2 and s.startswith('_') and s[1:].isalpha():
        return 0.8 * MATH[op][1]
    if op == 'norm' and len(s.strip()) > 1 and set(s.strip()) == {'_'}:
        return 5.5
    if s == '_-' and op == 'square bracket':
        return 6.2
    if op and s and s[0] in '₀₁₂₃₄₅₆₇₈₉':
        return MATH[op][2]
    if p.endswith('_{'):
        before = operator(pp)
        if before:
            if s.startswith(('\\', '{')) or s == '0':
                return 0.75 * MATH[before][1]
            if s.isdecimal() or s.isupper():
                return 0.3 * MATH[before][1]
    if op == 'norm' and (s.startswith('^') or s in {'²', ' <', ' >', '≤', ' ≤'}):
        return 5.5
    if p.strip() == '\\' and operator(pp) == 'norm' and s in {'le', 'ge', 'leq', 'geq'}:
        return 5.0
    if p.strip() == '_':
        op = operator(pp)
        if op and (s.startswith(('{', '\\')) or s.isdecimal()):
            if op == 'norm' and s.startswith('{{'):
                return 8.4
            return MATH[op][2]
        if s.isdecimal():
            k = base(pp)
            if k == 'user placeholder':
                return -8.8
            if k == 'code placeholder':
                return -3.5
            if k in {'name', 'spaced name'}:
                n = int(s)
                if k == 'spaced name':
                    return -3.46 if n <= 2 else -2.43 if n == 3 else -1.51
                return -2.61 if n <= 2 else -1.83 if n == 3 else -1.61
            return {'variable': -0.64, 'constant': -1.64,
                    'number': -1.1, 'word': -1.2}.get(k, 0.0)
    if len(s) > 1 and s.isalpha() and p.rstrip().endswith('_') and not p.endswith('__'):
        if s in {'this', 'super', 'export', 'class', 'import'}:
            return -4.0
        return 0.42
    if p.strip() == '__' and s.isdecimal():
        return -0.8
    return 0.0013


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p = pp = ''
    else:
        _, p, pp = carry
    s = prefix.token_strings[-1]
    if '\ufffd' in s:
        # Integral and norm signs can span several byte-level tokens.
        recent = [b for b, d in zip(prefix.token_bytes[-3:],
                                    prefix.document_ids[-3:]) if d == doc]
        text = b''.join(recent).decode('utf-8', 'ignore')
        if text and text[-1] in '∫∮∯∰∥‖∑∏∣':
            s = text[-1]
    return (doc, s, p), float(response(s, p, pp))

"""A document-initial pulse, modulated by the kind of its first token.

Ordinary later tokens get a near-zero background. At a document's first
position, words give a large positive pulse, whereas digits, punctuation,
and single whitespace characters give much less. Articles, this/that,
and the token "to" strengthen it; several forms of be/have and plural
pointing words weaken it. Han text gets a smaller pulse, Cyrillic text
and all-uppercase words get larger ones. Exact lexical differences and
small context-dependent fluctuations after the first token are omitted.
"""
import unicodedata
import regex

READS = ()


def initial_value(text):
    word = text.strip()
    lower = word.lower()
    if text.startswith('<|'):
        return 7.9
