"""Document-start detector (layers.1.mlp.down_proj:3250).

The component is silent inside a document and fires on the document's first token: the
first token of each row, and the first token after each document boundary. Attention can
see nothing before that token, so its value depends only on which token it is:

- articles, demonstratives, "to" and question words (the, a, this, to, what) are strongly
  positive;
- ALL-CAPS words and <|special|> tokens are high;
- ordinary words are moderately positive, CJK characters a bit less;
- spelled-out numbers (two, three, thousand) are negative;
- digits are about zero, other punctuation and whitespace slightly positive.

Every other position predicts 0.
"""

READS = ()

NUMBER_WORDS = {"two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
                "eleven", "twelve", "twenty", "thirty", "forty", "fifty", "sixty",
                "seventy", "eighty", "ninety", "hundred", "thousand", "million"}
OPENERS = {"the", "a", "an", "this", "that", "these", "those", "to",
           "what", "which", "when", "how", "why", "where", "who"}


def step(carry, prefix, upstream):
    t = prefix.position
    docs = prefix.document_ids
    if t > 0 and docs[t] == docs[t - 1]:
        return None, 0.0  # inside a document: silent
    w = prefix.token_strings[t].strip()
    if w.startswith("<|"):
        return None, 8.0
    if w.isdigit():
        return None, 0.0
    if not any(ch.isalpha() for ch in w):
        return None, 2.0
    if w.lower() in NUMBER_WORDS:
        return None, -5.0
    if len(w) > 1 and w.isupper():
        return None, 8.5
    if w.lower() in OPENERS:
        return None, 10.0
    if w.isascii():
        return None, 5.5
    return None, 4.0

