    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        decoder = codecs.getincrementaldecoder('utf8')('ignore')
        previous, last_char = '', ''
    else:
        _, decoder, previous, last_char = carry
    text = decoder.decode(prefix.token_bytes[-1])
    s = text.strip()
    value = lexical(text) - 0.0005
    if s in ('据', '據') and last_char in '。！？；，：.!?;,:\n ':
        value -= 3.8
    if re.fullmatch(r'[^A-Za-z]*[jJ]', previous) and text and text[0].isalpha():
        lower = text.lower()
        if lower.startswith('e'):
            value += 0.6
        elif lower.startswith('u'):
            value -= 0.7
        if re.fullmatch(r'[au][bcdfghjklmnpqrstvwxyz]e', lower):
            value += 2.5
        if re.match(r'[aeiou]([bcdfghjklmnpqrstvwxyz])\1', lower):
            value += 1.0
    if text:
        last_char = text[-1]
    return (doc, decoder, text, last_char), float(value)

"""Approximate an initial-token-run pulse from token spelling.

Underscored identifiers are strongest; code fragments and primitive C types
are also strong. Ordinary words, whitespace and digits have smaller pulses.
The pulse lasts through any repetition of the initial token. After that,
use a near-zero baseline.
These spelling classes intentionally omit individual-word variation.
"""
from wordfreq import zipf_frequency
import unicodedata

READS = ()
C_TYPES = frozenset(
    "void bool char short int long float double signed unsigned".split()
)


def initial_value(s):
    t = s.strip()
    letters = any(c.isalpha() for c in t)
    if any(unicodedata.category(c) == 'Cc' and c not in '\n\r\t' for c in s):
        return -15.0
    if t.startswith('_'):
        return (-16.4 if t.islower() else -12.8) if letters else -6.4
    if s in C_TYPES:
        return -11.0
    if letters and t.startswith(('.', '/')):
        return -4.0 if t.startswith('.') else -4.9
    if t.startswith('\\') and len(t) > 1:
        return -5.9
    if s.startswith('<|'):
        return -1.8
    if s.isspace():
        if '\r' in s:
            return -6.2 if '\n' in s else 2.1
        if '\t' in s:
            return -4.0
        if '\n' in s:
            return -2.5 if s.count('\n') == 1 else -0.7
        return -0.73 if len(s) == 1 else -1.5
    if len(t) == 1 and t in '0123456789':
        return -1.4
    if s == ',':
        return 0.16
    if t.isalpha() and t.istitle():
        if s.startswith(' '):
            return -1.8
        return -0.05 if zipf_frequency(t.lower(), 'en') > 6.7 else -0.87
    if t and not any(c.isalnum() for c in t):
        if '\n' in s:
            return -3.3
        if s.startswith(' '):
            return -2.7
    if len(t) <= 1:
        return -1.18
    common_word = (t.isalpha() and t.islower()
                   and zipf_frequency(t, 'en') > 5.6)
    return -1.3 if common_word else -2.2


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(prefix.token_strings[-1])
        return (doc, token, value), value
    if carry[1] == token:
        return carry, carry[2]
    # Once a different token occurs, the initial run is over for this document.
    return (doc, None, 0.005), 0.005

"""A unit/first-item signal, with a negative 'one selected from a set' signal.

Recognize spellings of one and first, boost 1 at list openings, and carry
that boost onto list punctuation. Short English and Chinese quantifier
patterns supply the negative counterpart; 'one hand' is a positive cue.
A few calendar and compass labels also receive positive responses. Values
are rounded training estimates, not a token-ID lookup. Rare spelling and
formatting effects, and much context-dependent variation, remain unmodeled.
"""
import re
import unicodedata
import regex

READS = ()
NUMBER_WORDS = {
    'one': .876, 'first': .965, 'single': .710, 'once': .708,
    'alone': .277, 'ones': .624, 'eleven': 1.16,
}
ASSOCIATED_LABELS = {
    'north': 1.12, 'northern': 1.12, 'january': .526,
    'november': 1.10, 'monday': .724,
}
SELECTORS = {'each': -1.62, 'which': -2.34, 'any': -1.28, 'every': -1.27}
# Quantifier spellings, inhibition, and extra inhibition across a token boundary.
CHINESE_QUANTIFIERS = (
    ('每', 1.917, 1.759),    # each
    ('某哪任', 2.067, 2.067),  # some / which / any
    ('同', 3.169, 2.234),    # the same one
    ('另又', 1.168, 0.0),    # another
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, position, list_one = '', '', 0, False
    else:
        _, tail, previous, position, list_one = carry
    s = prefix.token_strings[-1]
    text = s.strip()
    word = text.lower()
    line_one = False
    if s == '1':
        value = 1.023
        line_one = position > 0 and bool(
            not tail.strip() or re.search(r'\n[^\S\n]*$', tail))
        if position == 0:
            value = -.905  # The document-initial digit has a different response.
        if line_one:
            value += .457
            if re.search(r'[:：]\s*$', tail):
                value += .724
            if re.search(r'\n\s*\n\s*$', tail):
                value += .835
            if not any(c.isdigit() for c in tail[-80:]):
                value += .833
            if regex.search(r'\p{Script=Han}', tail[-80:]):
                value += 1.500
        if tail:
            value -= .029 * tail[-1].isdigit()
            value -= .091 * tail[-1].isalpha()
            value -= .085 * (tail[-1] in '[({')
            value += .184 * (tail[-1] == '.')
            value -= .287 * (tail[-1] in '+-=−*/')
        if previous == '1':
            value += .462
        if re.search(
            r'(?i)\b(chapter|section|step|scene|part|table|figure|lesson)\s+$',
            tail,
        ):
            value += .307
        if tail.rstrip(' \t').endswith('\\n'):
            value += 1.509
    else:
        value = NUMBER_WORDS.get(word, ASSOCIATED_LABELS.get(word, 0.0))
        if (word in NUMBER_WORDS and tail and tail[-1].isalpha()
                and not s[0].isspace()):
            value -= .444  # A spelling inside a longer word is a weaker cue.
        if (len(text) == 1 and text != '一'
                and unicodedata.numeric(text, None) == 1):
            value += 1.059
        if '一' in text:
            value += 1.561 if text == '一' else .153
            value += .980 * ('第一' in text)
            before_one = tail + text.split('一')[0]
            for quantifiers, strength, extra in CHINESE_QUANTIFIERS:
                if before_one and before_one[-1] in quantifiers:
                    value -= strength
                    if text.startswith('一'):
                        value -= extra
                    break
        if word == 'of' and re.search(r'(?i)\bone$', tail):
            value -= .070
            for q, amount in SELECTORS.items():
                if re.search(r'(?i)\b' + q + r'\s+one$', tail):
                    value += amount
        if word == 'hand' and re.search(r'(?i)\bone$', tail):
            value += 4.0 if re.search(r'(?i)\bon the one$', tail) else 1.7
        if previous == '1':
            if text and all(not c.isalnum() for c in text):
                value += .089
            if s.isspace():
                value += .091
            if list_one and text and text[0] in '.)':
                value += 1.907
            if text == ':':
                value += .322
            if text == '.':
                value += .365
            if text == ')':
                value += .329
    # Initial 1 can still introduce a list, despite its negative digit response.
    list_one = line_one or (s == '1' and position == 0)
    carry = (doc, (tail + s)[-160:], s, position + 1, list_one)
    return carry, value

programs.haiku:
"""Numbered-list "1" detector for layers.1.mlp.down_proj:3261.

The component fires on the digit 1 when it opens a numbered list item, i.e. a "1" at the
start of a line ("\n1. Preheat the oven"), strongest there (~2.6). The "." or ")" that
closes such a line-start marker fires about as strongly (~2.5). A "1" elsewhere (after a
space, a digit, a symbol) fires weakly (~1.0), and "one" / "first" (plus the CJK one, 一)
fire at about 0.9-1.0. The "1" that begins a document is slightly negative (-0.9).
Everything else is predicted as 0. Only the previous one or two tokens are read.
"""
READS = ()

ONE_WORDS = {" one", " One", "One", "one", " single", " once"}
FIRST_WORDS = {" first", " First", "First"}
ONE_CJK = {"一", "１", "¹", "₁"}
LIST_LABELS = {"1", "a", "A", "I", "i"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    prev2 = toks[-3] if len(toks) > 2 else ""
    new_doc = len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if cur == "1" or cur in ONE_CJK:
        if new_doc:
            return None, -0.9
        if "\n" in prev:
            return None, 2.6  # '1' starting a line: a numbered list item
        return None, 1.0
    if cur in (".", ")"):
        if prev in LIST_LABELS and "\n" in prev2:
            return None, 2.5  # '1.' at line start
        if prev in LIST_LABELS:
            return None, 0.6
    if cur in ONE_WORDS or cur in ONE_CJK:
        return None, 0.9
    if cur in FIRST_WORDS:
        return None, 1.0
    return None, 0.0

programs.sol:
"""Calendar spellings and date boundaries.

Weekday names are a strong cue, especially when split across tokens in European
languages. The space before the year and comma after a month/day are also cues.
Keep only a short text tail, resetting at each new document. This approximation
also includes two formatting responses: an opening title colon and middle dots.
"""
import calendar
import re

READS = ()
WEEKDAYS = {name.lower(): i for i, name in enumerate(calendar.day_name)}
MONTHS = {name.lower(): i for i, name in enumerate(calendar.month_name) if name}
ABBREVIATIONS = {name.lower() for name in calendar.month_abbr if name}
MONTH_RE = (r'(?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|'
            r'Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|'
            r'Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)')
MONTH_END = re.compile(r'\b'+MONTH_RE+r'$', re.I)
DAY_MONTH = re.compile(r'\b\d{1,2}(?:st|nd|rd|th)?\s+'+MONTH_RE+r'\.?$', re.I)
MONTH_DAY = re.compile(r'\b'+MONTH_RE+r'\.?\s+\d{1,2}(?:st|nd|rd|th)?[,]?$', re.I)
WEEKDAY_END = re.compile(
    r'\b(?:Mon(?:day)?|Tue(?:sday|s)?|Wed(?:nesday)?|Thu(?:rsday|rs?)?|'
    r'Fri(?:day)?|Sat(?:urday)?|Sun(?:day)?)\.?,?\s*$', re.I)
WORD_END = re.compile(r'[^\W\d_]+$', re.U)

# Names of weekdays in French and Spanish; strengths refer to a completing piece.
ROMANCE_DAYS = {}
for names, strengths in (
    ('lundi mardi mercredi jeudi vendredi samedi dimanche',
     (8.5, 13.0, 11.5, 16.0, 13.5, 11.5, 2.0)),
    ('lunes martes miércoles jueves viernes sábado domingo',
     (11.0, 13.5, 12.0, 14.0, 11.0, 5.0, 4.0)),
):
    ROMANCE_DAYS.update(zip(names.split(), strengths))
GERMAN_DAYS = ('montag', 'dienstag', 'mittwoch', 'donnerstag',
               'freitag', 'samstag', 'sonntag')
NORTHERN_DAYS = (
    'maandag dinsdag woensdag donderdag vrijdag zaterdag zondag '
    'måndag tisdag onsdag torsdag fredag lördag söndag '
    'mandag tirsdag lørdag søndag').split()
ITALIAN_DAYS = ('lunedì', 'martedì', 'mercoledì', 'giovedì', 'venerdì')
# Months, seasons, and related time words in other languages.
FOREIGN_TIME_WORDS = {}
for names, value in (
    ('janvier février juin agosto enero febrero junio julio', 1.4),
    ('mars avril mai août septiembre noviembre diciembre', 1.8),
    ('septembre novembre décembre', 2.0),
    ('octobre octubre', 2.8), ('marzo', 3.2), ('juillet', 3.8),
    ('januar februar märz april juni juli august '
     'september oktober november dezember', 1.5),
    ('gennaio febbraio aprile maggio giugno luglio '
     'settembre ottobre dicembre', 1.7),
    ('января февраля марта апреля мая июня июля '
     'августа сентября октября ноября декабря', 1.2),
    ('недели неделю', 4.1), ('måned', 5.2), ('printemps', 4.5),
    ('déjeuner dejeuner anno mayo noël', 3.0), ('monat', 2.8),
    ('semana', 1.8),
):
    FOREIGN_TIME_WORDS.update((name, value) for name in names.split())


# Completing spellings: weekdays, tomorrow, daytime, frequency, and calendar units.
COMPLETIONS = dict(FOREIGN_TIME_WORDS, **ROMANCE_DAYS)
COMPLETIONS.update((day, 9.5) for day in GERMAN_DAYS)
COMPLETIONS['mittwoch'] = 6.5
COMPLETIONS.update((day+'s', 7.0) for day in GERMAN_DAYS)
COMPLETIONS.update((day, 8.0) for day in NORTHERN_DAYS)
COMPLETIONS.update((day, 10.0) for day in ITALIAN_DAYS)
for words, strength in (
    ('yesterdays', 8.5), ('ciberlunes', 5.5), ('marted mittwo', 5.3),
    ('nay', 4.7), ('diesmal manchmal', 3.2), ('tage tagen tages', 1.2),
    ('domani', 7.8), ('demain lendemain', 3.8),
    ('mittags nachmittags idag fødselsdag', 6.5),
    ('damals niemals jemals', 2.2),
    ('semaine semaines semain settimane settimana', 4.3), ('settim', 2.5),
    ('fortnight', 5.5), ('tomorrow morrow', 8.5), ('midnight', 2.3),
    ('noite noche noches notte mese', 3.0), ('midi', 4.5),
):
    COMPLETIONS.update((word, strength) for word in words.split())


def split_time_word(joined, lower):
    """Recognize a completing piece of a weekday or another time word."""
    singular = joined[:-1] if joined.endswith('s') else joined
    if singular in WEEKDAYS:
        if lower == 'days':
            return 8.0
        return (3.0, 3.1, 5.3, 6.4, 5.0, 3.2, 3.0)[WEEKDAYS[singular]]
    if lower == 'ay' and joined.endswith('day'):
        return 4.5
    if joined.endswith('thursday'):
        return 6.0
    if joined in MONTHS:
        return 3.0 if len(lower) >= 3 else 1.0
    if joined in ('demain', 'lendemain') and lower == 'emain':
        return 7.2
    if joined.endswith(('morgen', 'middag', 'mittag', 'nachmittag')):
        return 6.3
    if joined.endswith(('woche', 'wochen', 'wochentag')):
        return 3.0
    return COMPLETIONS.get(joined)


def predict(token, before, text):
    word = token.strip()
    lower = word.lower()
    match = (WORD_END.search(text[-48:])
             if token[:1].isalpha() and word[-1:].isalpha() else None)
    joined = match.group().lower() if match else ''
    split = bool(joined and joined != lower and lower and lower[-1:].isalpha())

    if len(token) > 1 and not token.strip('·'):
        return -1.25
    if token == ':' and before == 'Title':
        return 5.21
    if lower.rstrip('s') in WEEKDAYS:
        day = WEEKDAYS[lower.rstrip('s')]
        if not before and lower in WEEKDAYS and word.istitle():
            return (-6.84, -7.09, -7.55, -6.75, -6.16, -4.91, -5.69)[day]
        return (1.05, 1.05, 1.1, 1.2, 2.3, 1.8, 1.7)[day]
    if split:
        value = split_time_word(joined, lower)
        if value is not None:
            return value

    if lower in MONTHS and word[:1].isupper():
        if not before and word.istitle():
            return (-2.36, -2.18, -2.50, -1.62, -0.35, -0.71,
                    -1.70, -0.64, -1.46, -0.22, -1.64, -1.21)[MONTHS[lower]-1]
        value = (0.0, -0.1, -0.4, -0.35, -0.35, -0.1,
                 -0.15, -0.3, -0.2, 0.3, 0.15, 0.1)[MONTHS[lower]-1]
        if re.search(r'\d(?:st|nd|rd|th)?\s*$', before):
            value += 0.9
        elif re.search(r'\b(?:in|since|during)\s*$', before, re.I):
            value += 0.4
        if WEEKDAY_END.search(before):
            value -= 2.7
        return value
    if lower in ABBREVIATIONS and word[:1].isupper():
        return 0.65
    if token == '/' and re.search(
        r'(?<![0-9/])(?:0?[1-9]|[12][0-9]|3[01])/'
        r'(?:0?[1-9]|[12][0-9]|3[01])$', before
    ):
        return 1.5
    if token in (' ', ',', '.', " '"):
        if DAY_MONTH.search(before):
            return 1.9 if token == ' ' else 0.25
        if MONTH_DAY.search(before):
            return {' ': 1.2, ',': 1.0, " '": 2.2, '.': 0.0}[token]
        if MONTH_END.search(before):
            return {'.': 0.85, ' ': 0.25, ',': 0.2, " '": 0.2}[token]
    if lower in FOREIGN_TIME_WORDS and lower not in MONTHS:
        date_context = re.search(r'(?:\d{1,2}|\b(?:de|en|au|in))\s*$', before, re.I)
        return FOREIGN_TIME_WORDS[lower] * (1.0 if date_context else 0.2)
    # Chinese weekdays/daytimes, Japanese weekdays, and Korean day words.
    if token in ('一', '二', '三', '四', '五', '六', '日', '天'):
        if before.endswith(('星期', '周', '週')):
            return 6.0
    if re.search(r'(?:周|週)[一二三四五六日天]$', token):
        return 1.6
    if token in ('上', '上的') and before.endswith(('早', '晚')):
        return 4.5
    if token in ('一', '二', '三', '四', '五', '六', '七', '八', '九', '十'):
        if before.endswith('初'):
            return 5.0
    if token == '日' and before.endswith('曜'):
        return 3.7
    if token == '일':
        if before.endswith('요'):
            return 7.0
        if before.endswith('매'):
            return 3.5
        if before.endswith('당') and not before.endswith('해당'):
            return 4.0
    if token in ('节', '節') and before.endswith(
        ('情人', '圣诞', '聖誕', '春', '中秋', '端午', '国庆', '國慶')
    ):
        return 3.0
    if lower in ('am', 'pm', '.m') and (
        re.search(r'\d[ :0-9]*\s*[ap]?$', before, re.I)
    ):
        return 0.65
    if lower == "'clock":
        return 1.3
    if lower == 'eve' and re.search(r"(?:Christmas|Year['’]s)\s*$", before):
        return 5.4
    if lower in ('spring', 'summer', 'autumn', 'winter'):
        return 0.5
    if lower in ('today', 'yesterday', 'tomorrow', 'now'):
        return -0.89 if word == 'Today' and not before else 0.15
    if lower == 'year':
        return 0.4 if re.search(r'\b(?:last|this|past|each|every)\s*$', before, re.I) else 0.05
    if lower in ('years', 'season', 'seasons'):
        return 0.18
    if lower == '-day':
        return 1.1 if before.lower().endswith('to') else 2.3
    if lower == 'day':
        if re.search(r'\b(?:some|judgment|election)\s*$', before, re.I):
            return 1.3
        return 0.5 if word == 'Day' else 0.0
    if lower in ('dag', 'dia', 'soir') and token[:1].isspace():
        return 2.4 if lower == 'dag' else 1.0
    if word == 'Tag' and token[:1].isspace():
        return 1.0
    if lower == 'weekend':
        return 0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = b'' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_bytes[-1]
    before = previous.decode('utf-8', 'ignore')
    text = (previous + raw).decode('utf-8', 'ignore')
    value = predict(prefix.token_strings[-1], before, text)
    return (doc, (previous + raw)[-200:]), float(value)
